style:
:host {
	--xh-brand: #920C24;
	--xh-brand-dark: #6E091B;
	--xh-brand-border: #E8B4BE;
	--xh-brand-soft: #F5D9DE;
	--xh-brand-softest: #FBEEF0;
	--xh-ok: #1F7A4D;
	--xh-font: "Merriweather", Georgia, "Times New Roman", serif;
}
.xh, .xh button { font-family: var(--xh-font); }
.xh { color: var(--text-color); font-size: 13px; line-height: 1.6; padding: 4px 0 24px; }
.xh button { cursor: pointer; }
.xh h1, .xh h2, .xh h3, .xh p { margin: 0; }

/* header */
.xh-head { display: flex; justify-content: space-between; align-items: flex-end; gap: 16px; flex-wrap: wrap;
	padding: 4px 0 20px; border-bottom: 1px solid var(--border-color); }
.xh-head h1 { font-size: 22px; line-height: 1.35; font-weight: 700; color: var(--heading-color, var(--text-color)); letter-spacing: -0.01em; }
.xh-head > div:first-child { flex: 1 1 360px; min-width: 0; }
.xh-lead { color: var(--text-muted); margin-top: 6px; max-width: 520px; }
.xh-actions { display: flex; gap: 8px; flex-wrap: wrap; }
.xh-btn { border: 1px solid var(--border-color); background: var(--card-bg); color: var(--text-color);
	border-radius: 8px; padding: 8px 14px; font-size: 12.5px; font-weight: 700; }
.xh-btn:hover { border-color: var(--xh-brand); color: var(--xh-brand); }
.xh-btn.xh-primary { background: var(--xh-brand); border-color: var(--xh-brand); color: #fff; }
.xh-btn.xh-primary:hover { background: var(--xh-brand-dark); color: #fff; }

/* sections */
.xh-sec { padding-top: 28px; }
.xh-sec-head { margin-bottom: 14px; }
.xh-tag { display: inline-block; font-size: 10.5px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase;
	color: var(--xh-brand); }
.xh-sec-head h2 { font-size: 17px; font-weight: 700; margin-top: 2px; color: var(--heading-color, var(--text-color)); }
.xh-sec-head p { color: var(--text-muted); margin-top: 2px; max-width: 640px; }

/* setup checklist */
.xh-setup { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 10px; }
.xh-item { display: flex; gap: 10px; align-items: flex-start; text-align: left; width: 100%;
	border: 1px solid var(--border-color); background: var(--card-bg); color: inherit; border-radius: 10px; padding: 12px; }
.xh-item:hover { border-color: var(--xh-brand-border); box-shadow: 0 1px 6px rgba(146, 12, 36, .08); }
.xh-check { flex: none; width: 20px; height: 20px; border-radius: 50%; border: 1.5px solid var(--gray-400, #c0c6cc);
	display: grid; place-items: center; font-size: 11px; color: #fff; margin-top: 1px; }
.xh-item.done .xh-check { background: var(--xh-ok); border-color: var(--xh-ok); }
.xh-item b { display: block; font-size: 13px; }
.xh-item small { display: block; color: var(--text-muted); font-size: 11.5px; line-height: 1.5; margin-top: 2px; }
.xh-state { display: inline-block; margin-top: 6px; font-size: 11px; font-weight: 700; color: var(--text-muted); }
.xh-item.done .xh-state { color: var(--xh-ok); }
.xh-item.todo .xh-state { color: var(--xh-brand); }

/* exam plans table */
.xh-plans { margin-bottom: 18px; }
.xh-pt { border: 1px solid var(--border-color); background: var(--card-bg); border-radius: 10px; overflow: hidden; }
.xh-pt-bar { display: flex; gap: 8px; flex-wrap: wrap; padding: 10px 12px; border-bottom: 1px solid var(--border-color); }
.xh-input { font-family: var(--xh-font); font-size: 12.5px; height: 32px; border: 1px solid var(--border-color); border-radius: 7px;
	background: var(--control-bg, #fff); color: var(--text-color); padding: 0 10px; }
.xh-input:focus { outline: none; border-color: var(--xh-brand); box-shadow: 0 0 0 2px var(--xh-brand-soft); }
.xh-pt-q { flex: 1 1 220px; min-width: 0; }
.xh-pt-scroll { overflow-x: auto; position: relative; }
.xh-table { width: 100%; border-collapse: collapse; font-size: 12.5px; font-variant-numeric: tabular-nums; }
.xh-table th { background: var(--subtle-fg, #f7f7f8); text-align: left; padding: 0; border-bottom: 1px solid var(--border-color); white-space: nowrap; }
.xh-table th.num, .xh-table td.num { text-align: right; }
.xh-sort { width: 100%; background: none; border: 0; padding: 9px 12px; font: inherit; font-size: 11px; font-weight: 700;
	letter-spacing: .04em; text-transform: uppercase; color: var(--text-muted); text-align: inherit; }
.xh-sort:hover, .xh-sort.on { color: var(--xh-brand); }
.xh-arrow { font-size: 9px; margin-left: 4px; }
.xh-table td { padding: 10px 12px; border-bottom: 1px solid var(--border-color); vertical-align: middle; }
.xh-table tbody tr:last-child td { border-bottom: 0; }
.xh-table tbody tr:hover td { background: var(--xh-brand-softest); }
.xh-table td.act { text-align: right; white-space: nowrap; }
.xh-table td:first-child { min-width: 220px; }
.xh-sub { display: block; color: var(--text-muted); font-size: 11.5px; margin-top: 1px; }
.xh-cell-link { background: none; border: 0; padding: 0; font: inherit; font-weight: 700; color: var(--xh-brand); text-align: left; }
.xh-cell-link:hover { text-decoration: underline; }
.xh-badge { display: inline-block; font-size: 11px; font-weight: 700; padding: 1px 8px; border-radius: 999px;
	background: var(--gray-100, #f1f2f4); color: var(--text-muted); }
.xh-badge.on { background: var(--xh-brand-softest); color: var(--xh-brand-dark); border: 1px solid var(--xh-brand-border); }
.xh-none { text-align: center; color: var(--text-muted); padding: 22px 12px !important; }
.xh-pt-foot { display: flex; justify-content: space-between; align-items: center; gap: 10px; flex-wrap: wrap;
	padding: 9px 12px; border-top: 1px solid var(--border-color); }
.xh-pager { display: flex; gap: 8px; align-items: center; }
.xh-btn.xh-sm { padding: 4px 10px; font-size: 12px; border-radius: 7px; }
.xh-btn:disabled { opacity: .45; cursor: default; }
.xh-btn:disabled:hover { border-color: var(--border-color); color: var(--text-color); }
.xh-progress { display: flex; flex-direction: column; gap: 5px; min-width: 150px; }
.xh-dots { display: flex; gap: 4px; }
.xh-dots i { flex: 1; height: 5px; border-radius: 3px; background: var(--gray-200, #e6e9ec); }
.xh-dots i.done { background: var(--xh-brand); }
.xh-dots i.now { background: var(--xh-brand-border); }
.xh-progress span { font-size: 11.5px; color: var(--text-muted); white-space: nowrap; }
.xh-progress span b { color: var(--text-color); }
.xh-empty { border: 1px dashed var(--xh-brand-border); background: var(--xh-brand-softest); border-radius: 10px;
	padding: 14px 16px; display: flex; justify-content: space-between; align-items: center; gap: 12px; flex-wrap: wrap; }
.xh-muted { color: var(--text-muted); font-size: 12px; }

/* five steps */
.xh-steps { list-style: none; margin: 0; padding: 0; position: relative; }
.xh-step { position: relative; display: grid; grid-template-columns: 40px minmax(0, 1fr); gap: 14px; padding-bottom: 14px; }
.xh-step::before { content: ""; position: absolute; left: 19px; top: 40px; bottom: 0; width: 2px; background: var(--xh-brand-soft); }
.xh-step:last-child::before { display: none; }
.xh-num { width: 40px; height: 40px; border-radius: 50%; background: var(--xh-brand); color: #fff;
	display: grid; place-items: center; font-weight: 900; font-size: 16px; position: relative; z-index: 1; }
.xh-body { border: 1px solid var(--border-color); background: var(--card-bg); border-radius: 10px; padding: 12px 14px; }
.xh-body h3 { font-size: 14.5px; font-weight: 700; }
.xh-body p { color: var(--text-muted); margin-top: 3px; }
.xh-do { margin: 8px 0 0; padding-left: 18px; }
.xh-do li { margin: 2px 0; }
.xh-uses { display: flex; gap: 6px; flex-wrap: wrap; align-items: center; margin-top: 10px; }
.xh-uses > span { font-size: 11px; color: var(--text-muted); margin-right: 2px; }
.xh-chip { border: 1px solid var(--xh-brand-border); background: var(--xh-brand-softest); color: var(--xh-brand-dark);
	border-radius: 999px; padding: 2px 10px; font-size: 11.5px; font-weight: 700; }
.xh-chip:hover { background: var(--xh-brand-soft); }

/* after results */
.xh-cards { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; }
.xh-card { text-align: left; border: 1px solid var(--border-color); background: var(--card-bg); color: inherit;
	border-radius: 10px; padding: 14px; display: flex; flex-direction: column; gap: 4px; }
.xh-card:hover { border-color: var(--xh-brand-border); box-shadow: 0 1px 6px rgba(146, 12, 36, .08); }
.xh-card b { font-size: 13.5px; }
.xh-card small { color: var(--text-muted); font-size: 11.5px; line-height: 1.5; }
.xh-card .xh-go { margin-top: 6px; color: var(--xh-brand); font-size: 12px; font-weight: 700; }

/* records */
.xh-links { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 0 18px;
	border: 1px solid var(--border-color); background: var(--card-bg); border-radius: 10px; padding: 6px 14px; }
.xh-row { display: flex; justify-content: space-between; align-items: center; gap: 8px; width: 100%; text-align: left;
	background: none; border: 0; border-bottom: 1px solid var(--border-color); color: inherit; padding: 9px 0; font-size: 12.5px; }
.xh-row:hover { color: var(--xh-brand); }
.xh-row em { font-style: normal; font-size: 10.5px; color: var(--text-muted); }

@media (max-width: 900px) {
	.xh-setup, .xh-cards, .xh-links { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 600px) {
	.xh-setup, .xh-cards, .xh-links { grid-template-columns: 1fr; }
	.xh-step { grid-template-columns: 32px minmax(0, 1fr); gap: 10px; }
	.xh-num { width: 32px; height: 32px; font-size: 14px; }
	.xh-step::before { left: 15px; top: 32px; }
}

script:
// Examination Management workspace home. Runs inside the custom block's shadow root.
const $root = root_element;
const esc = (v) => frappe.utils.escape_html(v == null ? "" : String(v));
const PLANNER = "slcm.slcm.page.examination_planner.examination_planner.";

// @font-face is ignored inside a shadow root, so the font is loaded on the page
if (!document.getElementById("er-theme-font")) {
	const l = document.createElement("link");
	l.id = "er-theme-font";
	l.rel = "stylesheet";
	l.href = "https://fonts.googleapis.com/css2?family=Merriweather:opsz,wght@18..144,300..900&display=swap";
	document.head.appendChild(l);
}

// type: DocType list | Single | Page | Report
const SETUP = [
	{ label: "Exam Component", type: "DocType", to: "Exam Component", hint: "The parts of an exam, such as Theory, Practical or Viva." },
	{ label: "Exam Assessment Type", type: "DocType", to: "Exam Assessment Type", hint: "Kinds of assessment, such as Mid Term, Quiz or End Term." },
	{ label: "Evaluation Schema", type: "DocType", to: "Evaluation Schema", hint: "Total and passing marks, and how components add up." },
	{ label: "Grading Schema", type: "DocType", to: "Grading Schema", hint: "Mark ranges for each grade and its grade point." },
	{ label: "Examination Settings", type: "Single", to: "Examination Settings", hint: "Rules for plans, eligibility, re-exams and improvement." },
];

const STEPS = [
	{
		title: "Create the plan and map courses",
		text: "One exam plan covers all the exams of an academic term. Its courses come from that term's Classes.",
		todo: ["Create the exam plan for the term", "Give every course an evaluation schema and a grading schema"],
		uses: [["Exam Plans", "DocType", "Exam Plan"], ["Course Schema Assignment", "DocType", "Course Schema Assignment"]],
	},
	{
		title: "Build the exam timetable",
		text: "Set the date, time, room and invigilator for each course. Room clashes, holidays and seat counts are checked for you.",
		todo: ["Schedule every course", "Set the assessment dates for each programme"],
		uses: [["Exam Assessment Schedule", "DocType", "Exam Assessment Schedule"]],
	},
	{
		title: "Students and marks",
		text: "One table shows every course. Add students from their Classes, check attendance eligibility, print barcodes, then open a course to enter or import its marks.",
		todo: ["Add students to every course", "Check attendance eligibility and print barcode sheets", "Make sure every student has marks or is marked absent"],
		uses: [["Student Course Marks", "DocType", "Student Course Marks"], ["Marks Import Log", "DocType", "Marks Import Log"]],
	},
	{
		title: "Finalise and publish results",
		text: "Submit and lock the marks, calculate term GPA, choose what students see, then publish to the student and parent portals.",
		todo: ["Submit and lock marks", "Calculate term results", "Publish results"],
		uses: [],
	},
];
const STEP_KEYS = ["plan", "timetable", "courses", "results"];
const STEP_SHORT = ["Plan & courses", "Exam timetable", "Students & marks", "Results & publish"];
// the server reports students and marks separately; the planner shows them as one step
const done_steps = (s) => ({ plan: s.plan, timetable: s.timetable, courses: s.students && s.marks, results: s.results });

const AFTER = [
	{ label: "Re Exam", type: "Page", to: "re-exam", hint: "Schedule a re-exam for students who failed and record the new marks." },
	{ label: "Improvement Exam", type: "Page", to: "improvement-exam", hint: "Let eligible students retake a course to improve their grade." },
];

const RECORDS = [
	["Consolidated Report", "Action", "consolidated"],
	["Exam Plans", "DocType", "Exam Plan"],
	["Exam Assessment Schedules", "DocType", "Exam Assessment Schedule"],
	["Student Course Marks", "DocType", "Student Course Marks"],
	["Course Schema Assignment", "DocType", "Course Schema Assignment"],
	["Marks Import Log", "DocType", "Marks Import Log"],
	["Schema Change Log", "DocType", "Schema Change Log"],
	["Course Schema Mapping Report", "Report", "Course Schema Mapping Report"],
	["Schema Change Audit", "Report", "Schema Change Audit"],
];

const target = (type, to) => (type === "Action" ? `data-act="${esc(to)}"` : `data-type="${esc(type)}" data-to="${esc(to)}"`);
const can_open = (type, to) => (type === "DocType" || type === "Single" ? frappe.model.can_read(to) : true);

function go(type, to) {
	if (type === "DocType") frappe.set_route("List", to);
	else if (type === "Single") frappe.set_route("Form", to);
	else if (type === "Report") frappe.set_route("query-report", to);
	else frappe.set_route(to);
}

function slot(name) {
	return $root.querySelector(`[data-slot="${name}"]`);
}

function render_setup(counts) {
	slot("setup").innerHTML = SETUP.filter((s) => can_open(s.type, s.to)).map((s) => {
		const n = counts[s.to];
		const state = s.type !== "DocType" ? "" : n ? "done" : "todo";
		const label = s.type !== "DocType" ? "Open settings" : n ? `${n} set up` : "Not set up yet";
		return `<button class="xh-item ${state}" ${target(s.type, s.to)}>
			<span class="xh-check">${state === "done" ? "✓" : ""}</span>
			<span><b>${esc(s.label)}</b><small>${esc(s.hint)}</small><span class="xh-state">${esc(label)}</span></span>
		</button>`;
	}).join("");
}

function render_steps() {
	slot("steps").innerHTML = STEPS.map((s, i) => `<li class="xh-step">
		<span class="xh-num">${i + 1}</span>
		<div class="xh-body">
			<h3>${esc(s.title)}</h3>
			<p>${esc(s.text)}</p>
			<ul class="xh-do">${s.todo.map((t) => `<li>${esc(t)}</li>`).join("")}</ul>
			<div class="xh-uses" ${s.uses.length ? "" : "hidden"}><span>Also opens:</span>
				${s.uses.filter((u) => can_open(u[1], u[2])).map((u) => `<button class="xh-chip" ${target(u[1], u[2])}>${esc(u[0])}</button>`).join("")}
			</div>
		</div>
	</li>`).join("");
}

// Exam plans table: search, status filter, sortable columns, pages
const PT = { rows: null, q: "", status: "", sort: "created", dir: -1, page: 0, size: 10 };
const PT_COLS = [
	["exam_name", "Exam plan"], ["status", "Status"],
	["courses", "Courses", "num"], ["students", "Students", "num"], ["step", "Progress"], ["published", "Published", "num"],
];

function next_step(p) {
	const d = done_steps(p.steps || {});
	const i = STEP_KEYS.findIndex((k) => !d[k]);
	return i === -1 ? STEP_KEYS.length : i;
}

function render_plans() {
	const el = slot("plans");
	const all = PT.rows;
	if (!all) {
		el.innerHTML = "";
		return;
	}
	if (!all.length) {
		el.innerHTML = `<div class="xh-empty">
			<p><b>No exam plans yet.</b> Create one for the academic term to start step 1.</p>
			<button class="xh-btn xh-primary" data-act="new-plan">+ New Exam Plan</button>
		</div>`;
		return;
	}
	if (!el.querySelector(".xh-pt")) {
		const statuses = [...new Set(all.map((p) => p.status).filter(Boolean))].sort();
		el.innerHTML = `<div class="xh-pt">
			<div class="xh-pt-bar">
				<input type="search" class="xh-input xh-pt-q" placeholder="Search exam plan or term" aria-label="Search exam plans">
				<select class="xh-input xh-pt-status" aria-label="Filter by status"><option value="">All statuses</option>
					${statuses.map((x) => `<option>${esc(x)}</option>`).join("")}</select>
				<select class="xh-input xh-pt-size" aria-label="Rows per page">
					${[10, 25, 50].map((n) => `<option value="${n}">${n} per page</option>`).join("")}</select>
			</div>
			<div class="xh-pt-scroll"><table class="xh-table">
				<thead><tr>${PT_COLS.map(([k, l, c]) => `<th class="${c || ""}"><button class="xh-sort" data-sort="${k}">${esc(l)}<span class="xh-arrow"></span></button></th>`).join("")}<th></th></tr></thead>
				<tbody></tbody>
			</table></div>
			<div class="xh-pt-foot"><span class="xh-muted xh-pt-info"></span><span class="xh-pager"></span></div>
		</div>`;
		el.querySelector(".xh-pt-q").addEventListener("input", (e) => { PT.q = e.target.value.trim().toLowerCase(); PT.page = 0; draw_plan_rows(); });
		el.querySelector(".xh-pt-status").addEventListener("change", (e) => { PT.status = e.target.value; PT.page = 0; draw_plan_rows(); });
		el.querySelector(".xh-pt-size").addEventListener("change", (e) => { PT.size = +e.target.value; PT.page = 0; draw_plan_rows(); });
	}
	draw_plan_rows();
}

function draw_plan_rows() {
	const el = slot("plans");
	let rows = PT.rows.filter((p) => (!PT.status || p.status === PT.status)
		&& (!PT.q || `${p.exam_name || p.name} ${p.term || ""}`.toLowerCase().includes(PT.q)));
	const key = (p) => (PT.sort === "step" ? next_step(p) : p[PT.sort]);
	rows.sort((a, b) => {
		const x = key(a), y = key(b);
		const c = typeof x === "number" && typeof y === "number" ? x - y : String(x ?? "").localeCompare(String(y ?? ""), undefined, { numeric: true });
		return c * PT.dir;
	});
	const pages = Math.max(1, Math.ceil(rows.length / PT.size));
	PT.page = Math.min(PT.page, pages - 1);
	const shown = rows.slice(PT.page * PT.size, (PT.page + 1) * PT.size);

	el.querySelector("tbody").innerHTML = shown.map((p) => {
		const n = next_step(p);
		const d = done_steps(p.steps || {});
		const dots = STEP_KEYS.map((k, i) => `<i class="${d[k] && i < n ? "done" : i === n ? "now" : ""}"></i>`).join("");
		const label = n === STEP_KEYS.length ? "<b>All steps done</b>" : `Step ${n + 1}: <b>${esc(STEP_SHORT[n])}</b>`;
		return `<tr>
			<td><button class="xh-cell-link" data-plan="${esc(p.name)}">${esc(p.exam_name || p.name)}</button>
				<small class="xh-sub">${esc(p.term || "")}</small></td>
			<td><span class="xh-badge ${p.status === "Active" ? "on" : ""}">${esc(p.status || "—")}</span></td>
			<td class="num">${p.courses || 0}</td>
			<td class="num">${p.students || 0}</td>
			<td><div class="xh-progress"><div class="xh-dots">${dots}</div><span>${label}</span></div></td>
			<td class="num">${p.published ? `${p.published} / ${p.students || 0}` : "0"}</td>
			<td class="act"><button class="xh-btn xh-sm" data-plan="${esc(p.name)}">${n === STEP_KEYS.length ? "Open" : "Continue"}</button></td>
		</tr>`;
	}).join("") || `<tr><td colspan="7" class="xh-none">No exam plans match.</td></tr>`;

	el.querySelectorAll(".xh-sort").forEach((b) => {
		const on = b.dataset.sort === PT.sort;
		b.classList.toggle("on", on);
		b.querySelector(".xh-arrow").textContent = on ? (PT.dir === 1 ? "▲" : "▼") : "";
		b.closest("th").setAttribute("aria-sort", on ? (PT.dir === 1 ? "ascending" : "descending") : "none");
	});
	const from = rows.length ? PT.page * PT.size + 1 : 0;
	el.querySelector(".xh-pt-info").textContent =
		`Showing ${from}–${PT.page * PT.size + shown.length} of ${rows.length} exam plan${rows.length === 1 ? "" : "s"}`;
	el.querySelector(".xh-pager").innerHTML = pages < 2 ? "" :
		`<button class="xh-btn xh-sm" data-page="${PT.page - 1}" ${PT.page ? "" : "disabled"}>‹ Prev</button>
		<span class="xh-muted">Page ${PT.page + 1} of ${pages}</span>
		<button class="xh-btn xh-sm" data-page="${PT.page + 1}" ${PT.page < pages - 1 ? "" : "disabled"}>Next ›</button>`;
}

function render_after() {
	slot("after").innerHTML = AFTER.filter((a) => can_open(a.type, a.to)).map((a) => `<button class="xh-card" ${target(a.type, a.to)}>
		<b>${esc(a.label)}</b><small>${esc(a.hint)}</small><span class="xh-go">Open →</span>
	</button>`).join("");
}

function render_records() {
	slot("records").innerHTML = RECORDS.filter((r) => can_open(r[1], r[2])).map((r) => `<button class="xh-row" ${target(r[1], r[2])}>
		<span>${esc(r[0])}</span><em>${r[1] === "Report" ? "Report" : r[1] === "Action" ? "Excel" : "List"}</em>
	</button>`).join("");
}

function new_plan() {
	frappe.set_route("examination-planner").then(() => {
		const planner = frappe.pages["examination-planner"] && frappe.pages["examination-planner"].planner;
		if (planner && planner.new_plan_dialog) planner.new_plan_dialog();
	});
}

$root.addEventListener("click", (e) => {
	const btn = e.target.closest("button");
	if (!btn) return;
	if (btn.dataset.sort) {
		PT.dir = PT.sort === btn.dataset.sort ? -PT.dir : 1;
		PT.sort = btn.dataset.sort;
		draw_plan_rows();
	} else if (btn.dataset.page !== undefined) {
		PT.page = +btn.dataset.page;
		draw_plan_rows();
	} else if (btn.dataset.act === "consolidated") {
		// the report dialog lives in the shared exam helpers
		frappe.require("/assets/slcm/js/exam/common.js", () => slcm.exam_ui.consolidated_report());
	} else if (btn.dataset.act === "new-plan") {
		new_plan();
	} else if (btn.dataset.plan) {
		frappe.set_route("examination-planner", btn.dataset.plan);
	} else if (btn.dataset.route) {
		frappe.set_route(btn.dataset.route);
	} else if (btn.dataset.to) {
		go(btn.dataset.type, btn.dataset.to);
	}
});

render_setup({});
render_steps();
render_after();
render_records();

Promise.all(
	SETUP.filter((s) => s.type === "DocType" && frappe.model.can_read(s.to))
		.map((s) => frappe.db.count(s.to).then((n) => [s.to, n]))
).then((pairs) => render_setup(Object.fromEntries(pairs)));

// The planner API is limited to these roles; skip it for anyone else rather than show an error
if (frappe.user.has_role(["System Manager", "Academics User"])) {
	frappe.xcall(PLANNER + "get_plan_list").then((plans) => {
		PT.rows = plans || [];
		render_plans();
	});
}

style:
:host {
	--ah-brand: #920C24;
	--ah-brand-dark: #6E091B;
	--ah-brand-border: #E8B4BE;
	--ah-brand-softest: #FBEEF0;
	--ah-ok: #1F7A4D;
	--ah-font: "Merriweather", Georgia, "Times New Roman", serif;
}
.ah, .ah button { font-family: var(--ah-font); }
.ah { color: var(--text-color); font-size: 13px; line-height: 1.6; padding: 4px 0 24px; }
.ah button { cursor: pointer; }
.ah h1, .ah h2, .ah h3, .ah p { margin: 0; }
.ah [hidden] { display: none !important; }

/* header */
.ah-head { display: flex; justify-content: space-between; align-items: flex-end; gap: 16px; flex-wrap: wrap;
	padding: 4px 0 20px; border-bottom: 1px solid var(--border-color); }
.ah-head > div:first-child { flex: 1 1 360px; min-width: 0; }
.ah-head h1 { font-size: 22px; line-height: 1.35; font-weight: 700; color: var(--heading-color, var(--text-color)); }
.ah-lead { color: var(--text-muted); margin-top: 6px; max-width: 560px; }
.ah-actions { display: flex; gap: 8px; flex-wrap: wrap; }
.ah-btn { border: 1px solid var(--border-color); background: var(--card-bg); color: var(--text-color);
	border-radius: 8px; padding: 8px 14px; font-size: 12.5px; font-weight: 700; }
.ah-btn:hover { border-color: var(--ah-brand); color: var(--ah-brand); }
.ah-btn.ah-primary { background: var(--ah-brand); border-color: var(--ah-brand); color: #fff; }
.ah-btn.ah-primary:hover { background: var(--ah-brand-dark); color: #fff; }

/* sections */
.ah-sec { padding-top: 26px; }
.ah-sec-head { margin-bottom: 12px; }
.ah-tag { display: inline-block; font-size: 10.5px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--ah-brand); }
.ah-sec-head h2 { font-size: 17px; font-weight: 700; margin-top: 2px; color: var(--heading-color, var(--text-color)); }
.ah-sec-head p { color: var(--text-muted); margin-top: 2px; max-width: 640px; }

/* today tiles */
.ah-today { display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); gap: 10px; }
.ah-tile { display: flex; flex-direction: column; align-items: flex-start; gap: 2px; text-align: left; color: inherit;
	background: var(--card-bg); border: 1px solid var(--border-color); border-radius: 10px; padding: 12px 14px; }
.ah-tile:hover { border-color: var(--ah-brand-border); box-shadow: 0 1px 6px rgba(146, 12, 36, .08); }
.ah-tile span { font-size: 12px; color: var(--text-muted); }
.ah-tile b { font-size: 24px; line-height: 1.2; font-variant-numeric: tabular-nums; }
.ah-tile small { font-size: 11px; color: var(--text-muted); }
.ah-tile.zero b { color: var(--text-muted); }

/* attention */
.ah-attn { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; }
.ah-flag { display: flex; align-items: center; gap: 12px; text-align: left; color: inherit; width: 100%;
	background: var(--card-bg); border: 1px solid var(--border-color); border-left: 3px solid var(--ah-brand); border-radius: 10px; padding: 10px 14px; }
.ah-flag:hover { border-color: var(--ah-brand); }
.ah-flag b { font-size: 20px; min-width: 48px; font-variant-numeric: tabular-nums; color: var(--ah-brand); }
.ah-flag small { display: block; color: var(--text-muted); font-size: 11.5px; }
.ah-flag em { margin-left: auto; font-style: normal; font-weight: 700; font-size: 12px; color: var(--ah-brand); white-space: nowrap; }
.ah-calm { grid-column: 1 / -1; color: var(--text-muted); background: var(--card-bg); border: 1px dashed var(--border-color); border-radius: 10px; padding: 12px 14px; }

/* setup checklist */
.ah-setup { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 10px; }
.ah-item { display: flex; gap: 10px; align-items: flex-start; text-align: left; width: 100%;
	border: 1px solid var(--border-color); background: var(--card-bg); color: inherit; border-radius: 10px; padding: 12px; }
.ah-item:hover { border-color: var(--ah-brand-border); box-shadow: 0 1px 6px rgba(146, 12, 36, .08); }
.ah-check { flex: none; width: 20px; height: 20px; border-radius: 50%; border: 1.5px solid var(--gray-400, #c0c6cc);
	display: grid; place-items: center; font-size: 11px; color: #fff; margin-top: 1px; }
.ah-item.done .ah-check { background: var(--ah-ok); border-color: var(--ah-ok); }
.ah-item b { display: block; font-size: 13px; }
.ah-item small { display: block; color: var(--text-muted); font-size: 11.5px; line-height: 1.5; margin-top: 2px; }
.ah-state { display: inline-block; margin-top: 6px; font-size: 11px; font-weight: 700; color: var(--text-muted); }
.ah-item.done .ah-state { color: var(--ah-ok); }
.ah-item.todo .ah-state { color: var(--ah-brand); }
.ah-badge { display: inline-block; margin-left: 6px; font-size: 10px; font-weight: 700; letter-spacing: .04em; text-transform: uppercase;
	color: var(--text-muted); border: 1px solid var(--border-color); border-radius: 999px; padding: 0 7px; vertical-align: 1px; }

/* steps */
.ah-steps { list-style: none; margin: 0; padding: 0; display: grid; gap: 10px; }
.ah-step { display: flex; gap: 14px; background: var(--card-bg); border: 1px solid var(--border-color); border-radius: 10px; padding: 14px 16px; }
.ah-num { flex: none; width: 28px; height: 28px; border-radius: 50%; background: var(--ah-brand-softest); color: var(--ah-brand);
	border: 1px solid var(--ah-brand-border); display: grid; place-items: center; font-weight: 700; }
.ah-body { min-width: 0; }
.ah-body h3 { font-size: 14px; font-weight: 700; }
.ah-body p { color: var(--text-muted); margin-top: 2px; }
.ah-uses { display: flex; gap: 6px; flex-wrap: wrap; align-items: center; margin-top: 8px; }
.ah-uses > span { font-size: 11.5px; color: var(--text-muted); }
.ah-chip { border: 1px solid var(--border-color); background: var(--card-bg); color: var(--text-color); border-radius: 999px; padding: 2px 10px; font-size: 11.5px; font-weight: 700; }
.ah-chip:hover { border-color: var(--ah-brand); color: var(--ah-brand); }

/* records */
.ah-links { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 0 18px; }
.ah-row { display: flex; justify-content: space-between; align-items: center; gap: 10px; text-align: left; width: 100%;
	border: 0; border-bottom: 1px solid var(--border-color); background: none; color: inherit; padding: 9px 2px; }
.ah-row:hover span { color: var(--ah-brand); }
.ah-row em { font-style: normal; font-size: 11px; color: var(--text-muted); }

@media (max-width: 1100px) {
	.ah-today { grid-template-columns: repeat(3, minmax(0, 1fr)); }
	.ah-setup, .ah-links { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 640px) {
	.ah-today { grid-template-columns: repeat(2, minmax(0, 1fr)); }
	.ah-setup, .ah-links, .ah-attn { grid-template-columns: minmax(0, 1fr); }
}

script:
// Attendance workspace home. Runs inside the custom block's shadow root.
const $root = root_element;
const esc = (v) => frappe.utils.escape_html(v == null ? "" : String(v));
const num = (v) => (v == null ? "—" : format_number(v, null, 0));
const API = "slcm.slcm.page.attendance_dashboard.attendance_dashboard.";
const TODAY = frappe.datetime.get_today();
const DAY = ["between", [TODAY, TODAY + " 23:59:59"]];

// @font-face is ignored inside a shadow root, so the font is loaded on the page
if (!document.getElementById("er-theme-font")) {
	const l = document.createElement("link");
	l.id = "er-theme-font";
	l.rel = "stylesheet";
	l.href = "https://fonts.googleapis.com/css2?family=Merriweather:opsz,wght@18..144,300..900&display=swap";
	document.head.appendChild(l);
}

// [label, key in get_home().today, doctype, list filters, note]
const TODAY_TILES = [
	["Sessions", "sessions", "Attendance Session", { session_date: TODAY }, "classes today"],
	["Marked", "marked", "Attendance Session", { session_date: TODAY, attendance_marked: 1 }, "sessions with attendance"],
	["Present", "present", "Student Attendance", { attendance_date: TODAY, status: ["in", ["Present", "Late", "OD"]] }, "incl. late and OD"],
	["Absent", "absent", "Student Attendance", { attendance_date: TODAY, status: "Absent" }, ""],
	["RFID swipes", "swipes", "RFID SQL Punch Log", { punch_time: DAY }, "pulled so far"],
	["Not matched", "unmatched", "Page", "attendance-sync", "see Attendance Sync"],
];

// [label, key in get_home().attention, what it means, type, to, filters]
const ATTENTION = [
	["Condonation requests", "condonation", "waiting for approval", "DocType", "Student Attendance Condonation", { final_status: ["in", ["Pending", "May Be Approved"]] }],
	["FA / MFA applications", "fa_mfa", "waiting for approval", "DocType", "FA MFA Application", { status: "Pending" }],
	["Past sessions not marked", "not_marked", "no attendance was taken", "DocType", "Attendance Session",
		{ session_date: ["<", TODAY], attendance_marked: 0, session_status: ["not in", ["Cancelled", "Postponed"]] }],
	["RFID swipes not matched", "unmatched", "sync them to a class or check the setup", "Page", "attendance-sync"],
];

// key = what get_home().setup counts; rfid marks the RFID-only items
const SETUP = [
	{ label: "Attendance Settings", type: "Single", to: "Attendance Settings", hint: "Minimum attendance %, condonation rules and alerts." },
	{ label: "Attendance Period", type: "DocType", to: "Attendance Period", key: "Attendance Period", hint: "The periods of the teaching day." },
	{ label: "Room", type: "DocType", to: "Room", key: "Room", hint: "Rooms that classes and readers are in." },
	{ label: "RFID Device", type: "DocType", to: "RFID Device", key: "RFID Device", rfid: 1, hint: "One per card reader, using its terminal ID." },
	{ label: "Device Room Mapping", type: "DocType", to: "RFID Device Room Mapping", key: "RFID Device Room Mapping", rfid: 1, hint: "Which room each reader is in." },
	{ label: "Student cards", type: "Page", to: "rfid-mapping", key: "Student Master", rfid: 1, hint: "The RFID card number on each active student." },
	{ label: "RFID Agent", type: "Single", to: "RFID SQL Agent Settings", key: "rfid_agent", rfid: 1, flag: 1, hint: "Pulls swipes from the campus SQL Server." },
];

const STEPS = [
	{
		title: "Plan the classes",
		text: "Each Time Table entry creates an Attendance Session for that class meeting. Changing or deleting the entry updates its session.",
		uses: [["Time Table", "DocType", "Time Table"], ["Office Hours", "DocType", "Office Hours Group"]],
	},
	{
		title: "Run the session",
		text: "The faculty member opens the session. For RFID classes they activate RFID, which accepts swipes for a set number of minutes.",
		uses: [["Attendance Session", "DocType", "Attendance Session"]],
	},
	{
		title: "Mark attendance",
		text: "Mark by hand with the Student Attendance Tool, or let RFID do it: swipes are matched to the class in that room every minute. Swipes that can't be matched wait in Attendance Sync.",
		uses: [["Student Attendance Tool", "Single", "Student Attendance Tool"], ["Attendance Sync", "Page", "attendance-sync"], ["Student Attendance", "DocType", "Student Attendance"]],
	},
	{
		title: "Track percentages and eligibility",
		text: "Every marked session updates the student's Attendance Summary for that course, including whether they are eligible to sit the exam.",
		uses: [["Attendance Summary", "DocType", "Attendance Summary"], ["Summary report", "Page", "attendance-summary-report"]],
	},
	{
		title: "Handle exceptions",
		text: "Students below the minimum can apply for condonation. Students away on university duty or medical grounds apply for FA / MFA.",
		uses: [["Condonation", "DocType", "Student Attendance Condonation"], ["FA / MFA", "DocType", "FA MFA Application"]],
	},
];

const RECORDS = [
	["Attendance Dashboard", "Page", "attendance-dashboard"],
	["Attendance Quick View", "Page", "attendance-quick-view"],
	["Attendance Summary Report", "Page", "attendance-summary-report"],
	["Attendance Final Report", "Report", "Comprehensive Attendance Report"],
	["RFID Attendance Report", "Report", "RFID Attendance Report"],
	["Student Attendance", "DocType", "Student Attendance"],
	["Attendance Sessions", "DocType", "Attendance Session"],
	["Attendance Summary", "DocType", "Attendance Summary"],
	["RFID swipe log", "DocType", "Attendance Log"],
];

const PAGE_ROLES = {
	"rfid-sql-agent-dashboard": ["System Manager"],
	"attendance-sync": ["System Manager", "slcm_Programme Chair", "AAD", "AAD Staff"],
	"rfid-mapping": ["System Manager", "slcm_Faculty", "AAD", "AAD Staff"],
	"attendance-dashboard": ["System Manager", "AAD", "AAD Staff", "slcm_Programme Chair"],
};
function can_open(type, to) {
	if (type === "DocType" || type === "Single") return frappe.model.can_read(to);
	if (type === "Page" && PAGE_ROLES[to]) return frappe.user.has_role(PAGE_ROLES[to]);
	return true;
}

function go(type, to, filters) {
	if (type === "DocType") frappe.set_route("List", to, filters || {});
	else if (type === "Single") frappe.set_route("Form", to);
	else if (type === "Report") frappe.set_route("query-report", to);
	else frappe.set_route(to);
}

// click targets are kept by index so list filters can travel with them
const TARGETS = [];
function target(type, to, filters) {
	return `data-t="${TARGETS.push([type, to, filters]) - 1}"`;
}

function slot(name) {
	return $root.querySelector(`[data-slot="${name}"]`);
}

function render_today(t) {
	slot("today-date").textContent = moment(TODAY).format("dddd, D MMMM");
	slot("today").innerHTML = TODAY_TILES.filter((x) => (x[2] === "Page" ? can_open("Page", x[3]) : can_open("DocType", x[2]))).map((x) => {
		const v = t ? t[x[1]] : null;
		const tgt = x[2] === "Page" ? target("Page", x[3]) : target("DocType", x[2], x[3]);
		return `<button class="ah-tile ${v ? "" : "zero"}" ${tgt}>
			<span>${esc(x[0])}</span><b>${num(v)}</b><small>${esc(x[4])}</small></button>`;
	}).join("");
}

function render_attention(a) {
	if (!a) return;
	const rows = ATTENTION.filter((x) => a[x[1]] && can_open(x[3], x[4]));
	slot("attention").innerHTML = rows.length ? rows.map((x) => `<button class="ah-flag" ${target(x[3], x[4], x[5])}>
		<b>${num(a[x[1]])}</b><span>${esc(x[0])}<small>${esc(x[2])}</small></span><em>Open →</em>
	</button>`).join("") : `<div class="ah-calm">Nothing is waiting. Approvals, unmarked sessions and unmatched swipes show up here.</div>`;
}

function render_setup(s) {
	s = s || {};
	slot("setup").innerHTML = SETUP.filter((x) => can_open(x.type, x.to)).map((x) => {
		const n = x.key ? s[x.key] : undefined;
		let state = "", label = "Open settings";
		if (x.flag) {
			state = n ? "done" : n === 0 ? "todo" : "";
			label = n ? "Running" : n === 0 ? "Turned off" : "Open settings";
		} else if (x.key) {
			state = n ? "done" : n === 0 ? "todo" : "";
			label = n == null ? "…" : n ? `${num(n)} set up` : "Not set up yet";
		}
		return `<button class="ah-item ${state}" ${target(x.type, x.to)}>
			<span class="ah-check">${state === "done" ? "✓" : ""}</span>
			<span><b>${esc(x.label)}${x.rfid ? '<span class="ah-badge">RFID</span>' : ""}</b><small>${esc(x.hint)}</small><span class="ah-state">${esc(label)}</span></span>
		</button>`;
	}).join("");
}

function render_steps() {
	slot("steps").innerHTML = STEPS.map((s, i) => {
		const uses = s.uses.filter((u) => can_open(u[1], u[2]));
		return `<li class="ah-step">
			<span class="ah-num">${i + 1}</span>
			<div class="ah-body">
				<h3>${esc(s.title)}</h3>
				<p>${esc(s.text)}</p>
				<div class="ah-uses" ${uses.length ? "" : "hidden"}><span>Opens:</span>
					${uses.map((u) => `<button class="ah-chip" ${target(u[1], u[2])}>${esc(u[0])}</button>`).join("")}
				</div>
			</div>
		</li>`;
	}).join("");
}

function render_records() {
	slot("records").innerHTML = RECORDS.filter((r) => can_open(r[1], r[2])).map((r) => `<button class="ah-row" ${target(r[1], r[2])}>
		<span>${esc(r[0])}</span><em>${r[1] === "Report" ? "Report" : r[1] === "Page" ? "Page" : "List"}</em>
	</button>`).join("");
}

$root.querySelectorAll(".ah-actions [data-to]").forEach((b) => {
	if (!can_open(b.dataset.type, b.dataset.to)) b.hidden = true;
});

$root.addEventListener("click", (e) => {
	const btn = e.target.closest("button");
	if (!btn) return;
	if (btn.dataset.t !== undefined) {
		const [type, to, filters] = TARGETS[+btn.dataset.t];
		go(type, to, filters);
	} else if (btn.dataset.to) {
		go(btn.dataset.type, btn.dataset.to);
	}
});

render_today(null);
render_setup(null);
render_steps();
render_records();

frappe.xcall(API + "get_home").then((h) => {
	render_today(h.today);
	render_attention(h.attention);
	render_setup(h.setup);
});

// Fees workspace home. Runs inside the custom block's shadow root.
const $root = root_element;
const esc = (v) => frappe.utils.escape_html(v == null ? "" : String(v));
const num = (v) => (v == null ? "—" : format_number(v, null, 0));
const money = (v) => (v == null ? "—" : format_currency(v, "INR", 0));
const API = "slcm.slcm.page.fee_dashboard.fee_dashboard.";
const TODAY = frappe.datetime.get_today();
const IN_WEEK = frappe.datetime.add_days(TODAY, 7);
const MONTH_START = moment(TODAY).startOf("month").format("YYYY-MM-DD");
const OPEN = ["in", ["Pending", "Partially Paid", "Overdue"]];

// @font-face is ignored inside a shadow root, so the font is loaded on the page
if (!document.getElementById("er-theme-font")) {
	const l = document.createElement("link");
	l.id = "er-theme-font";
	l.rel = "stylesheet";
	l.href = "https://fonts.googleapis.com/css2?family=Merriweather:opsz,wght@18..144,300..900&display=swap";
	document.head.appendChild(l);
}

// [label, key in get_home().tiles, doctype, list filters (ay = current academic year), unit]
const TILES = (ay) => {
	const y = ay ? { academic_year: ay } : {};
	return [
		["Collected today", "today", "Fee Payment", { docstatus: 1, payment_date: TODAY }, "payments"],
		["Collected this month", "month", "Fee Payment", { docstatus: 1, payment_date: ["between", [MONTH_START, TODAY]] }, "payments"],
		["Outstanding", "outstanding", "Fee Demand", { ...y, status: OPEN }, "dues"],
		["Overdue", "overdue", "Fee Demand", { ...y, status: "Overdue" }, "dues"],
		["Due in 7 days", "due_week", "Fee Demand", { ...y, status: ["in", ["Pending", "Partially Paid"]], due_date: ["between", [TODAY, IN_WEEK]] }, "dues"],
		["Excess held", "excess", "Student Credit Note", { status: "Active", available_credit: [">", 0] }, "credit notes"],
	];
};

// [label, key in get_home().attention, what it means, type, to, filters]
const ATTENTION = [
	["Fee payments not submitted", "draft_payments", "no receipt until they are submitted", "DocType", "Fee Payment", { docstatus: 0 }],
	["Concessions in draft", "draft_concessions", "submit to apply them to the dues", "DocType", "Fee Concession", { docstatus: 0 }],
	["Refunds in draft", "draft_refunds", "waiting for approval", "DocType", "Fee Refund", { docstatus: 0 }],
	["Overdue dues", "overdue", "past the due date and not fully paid", "DocType", "Fee Demand", { status: "Overdue" }],
	["Fee notifications not generated", "not_generated", "published, but dues were never generated", "DocType", "Fee Notification",
		{ status: "Published", generation_log: ["is", "not set"] }],
	["Failed online payments", "failed_online", "in the last 30 days", "DocType", "Online Payment Log", { status: "Failed" }],
	["Students without a fee structure", "no_structure", "active students; their fee totals stay empty", "DocType", "Student Master",
		{ student_status: "Active", fee_structure: ["is", "not set"] }],
	["Fee certificate requests", "certificates", "still in draft", "DocType", "Fee Certificate Request", { status: "Draft" }],
];

// key = what get_home().setup counts
const SETUP = [
	{ label: "Fee Component", type: "DocType", to: "Fee Component", key: "Fee Component", hint: "Every kind of charge: tuition, hostel, exam, fines. Set GST here." },
	{ label: "Fee Structure", type: "DocType", to: "Fee Structure", key: "Fee Structure", hint: "Amounts per programme, year and category, with Indian and foreign rates." },
	{ label: "Fee Notification", type: "DocType", to: "Fee Notification", key: "Fee Notification", hint: "Published for this academic year to raise the annual dues." },
	{ label: "Payment Gateway", type: "DocType", to: "Payment Gateway", key: "Payment Gateway", hint: "Razorpay / Easebuzz for online payment on the student portal." },
	{ label: "Fee reminders", type: "Single", to: "Student Portal Settings", key: "reminders", flag: 1, hint: "Emails 7 days and 1 day before the due date, and after it." },
	{ label: "Fee Certificate Settings", type: "Single", to: "Fee Certificate Settings", hint: "Purposes, templates and letterheads for fee certificates." },
];

const STEPS = [
	{
		title: "Set the fees",
		text: "Create the Fee Components, then one Fee Structure per programme and year (and per category where amounts differ). Foreign students are charged the structure's foreign rates.",
		uses: [["Fee Component", "DocType", "Fee Component"], ["Fee Structure", "DocType", "Fee Structure"], ["Bulk Fee Structure Update", "DocType", "Bulk Fee Structure Update"]],
	},
	{
		title: "Raise the annual dues",
		text: "Publish a Fee Notification and generate demands. Each student gets one Fee Demand per component, priced from their own Fee Structure. Dues can also be uploaded from the Excel sheet.",
		uses: [["Fee Notification", "DocType", "Fee Notification"], ["Generation Log", "DocType", "Fee Demand Generation Log"], ["Fee Demand", "DocType", "Fee Demand"]],
	},
	{
		title: "Dues raised by events",
		text: "Re-exam and course re-registration, revaluation, hostel allocation, fines, deferral and convocation raise their own Fee Demand when the record is saved or submitted.",
		uses: [["Re Exam Registration", "DocType", "Re Exam Registration"], ["Course Reregistration", "DocType", "Course Reregistration"],
			["Revaluation Request", "DocType", "Revaluation Request"], ["Hostel Fine", "DocType", "Hostel Fine"]],
	},
	{
		title: "Collect payments",
		text: "Students pay online on the portal, or the accounts office records a Fee Payment (one at a time or by bulk upload). Submitting it settles the dues and issues the receipt.",
		uses: [["Student fees", "Page", "student-fee-management"], ["Fee Payment", "DocType", "Fee Payment"], ["Bulk Fee Collection", "DocType", "Bulk Fee Collection"]],
	},
	{
		title: "Adjust dues",
		text: "Concessions and financial aid reduce a due, Fine Imposition adds late fees, and money paid twice or cancelled dues move to excess, where it can pay other dues.",
		uses: [["Fee Concession", "DocType", "Fee Concession"], ["Fine Imposition", "DocType", "Fine Imposition"], ["Student Credit Note", "DocType", "Student Credit Note"]],
	},
	{
		title: "Refunds & certificates",
		text: "Refund from a due or from excess, and issue fee certificates for loans and scholarships.",
		uses: [["Fee Refund", "DocType", "Fee Refund"], ["Fee Certificates", "Page", "fee-certificates"]],
	},
];

const RECORDS = [
	["Fees Dashboard", "Page", "fee-dashboard"],
	["Student Fee Management", "Page", "student-fee-management"],
	["Due-wise & outstanding reports", "Page", "fee-reports"],
	["Defaulter List", "Report", "Defaulter List"],
	["Collection Summary", "Report", "Collection Summary"],
	["Fee Demand Register", "Report", "Fee Demand Register"],
	["Receipt Register", "Report", "Receipt Register"],
	["Payment Settlement Report", "Report", "Payment Settlement Report"],
	["Failed Payment Report", "Report", "Failed Payment Report"],
	["Zoho journal upload", "Report", "Fee Payment Zoho Journal Upload"],
	["Fee Demands", "DocType", "Fee Demand"],
	["Fee Payments", "DocType", "Fee Payment"],
	["Fee Receipts", "DocType", "Fee Receipt"],
	["Fee Certificates", "Page", "fee-certificates"],
];

const FEE_ROLES = ["System Manager", "Campus Admin", "Accounts Manager", "Accounts User"];
const PAGE_ROLES = {
	"fee-dashboard": FEE_ROLES,
	"student-fee-management": FEE_ROLES,
	"fee-reports": FEE_ROLES,
	"fee-certificates": FEE_ROLES,
};
function can_open(type, to) {
	if (type === "DocType" || type === "Single") return frappe.model.can_read(to);
	if (type === "Page" && PAGE_ROLES[to]) return frappe.user.has_role(PAGE_ROLES[to]);
	return true;
}

function go(type, to, filters) {
	if (type === "DocType") frappe.set_route("List", to, filters || {});
	else if (type === "Single") frappe.set_route("Form", to);
	else if (type === "Report") frappe.set_route("query-report", to);
	else frappe.set_route(to);
}

// click targets are kept by index so list filters can travel with them
const TARGETS = [];
function target(type, to, filters) {
	return `data-t="${TARGETS.push([type, to, filters]) - 1}"`;
}

function slot(name) {
	return $root.querySelector(`[data-slot="${name}"]`);
}

function render_tiles(t, ay) {
	slot("money-title").textContent = ay ? `Collections & dues · ${ay}` : "Collections & dues";
	slot("tiles").innerHTML = TILES(ay).filter((x) => can_open("DocType", x[2])).map((x) => {
		const v = t ? t[x[1]] : null;
		return `<button class="fh-tile ${v && v.amount ? "" : "zero"}" ${target("DocType", x[2], x[3])}>
			<span>${esc(x[0])}</span><b>${money(v ? v.amount : null)}</b><small>${v ? `${num(v.count)} ${esc(v.count === 1 ? x[4].replace(/s$/, "") : x[4])}` : ""}</small></button>`;
	}).join("");
}

function render_attention(a) {
	if (!a) return;
	const rows = ATTENTION.filter((x) => a[x[1]] && can_open(x[3], x[4]));
	slot("attention").innerHTML = rows.length ? rows.map((x) => `<button class="fh-flag" ${target(x[3], x[4], x[5])}>
		<b>${num(a[x[1]])}</b><span>${esc(x[0])}<small>${esc(x[2])}</small></span><em>Open →</em>
	</button>`).join("") : `<div class="fh-calm">Nothing is waiting. Draft payments, overdue dues and pending approvals show up here.</div>`;
}

function render_setup(s) {
	s = s || {};
	slot("setup").innerHTML = SETUP.filter((x) => can_open(x.type, x.to)).map((x) => {
		const n = x.key ? s[x.key] : undefined;
		let state = "", label = "Open settings";
		if (x.flag) {
			state = n ? "done" : n === 0 ? "todo" : "";
			label = n ? "Turned on" : n === 0 ? "Turned off" : "Open settings";
		} else if (x.key) {
			state = n ? "done" : n === 0 ? "todo" : "";
			label = n == null ? "…" : n ? `${num(n)} set up` : "Not set up yet";
		}
		return `<button class="fh-item ${state}" ${target(x.type, x.to)}>
			<span class="fh-check">${state === "done" ? "✓" : ""}</span>
			<span><b>${esc(x.label)}</b><small>${esc(x.hint)}</small><span class="fh-state">${esc(label)}</span></span>
		</button>`;
	}).join("");
}

function render_steps() {
	slot("steps").innerHTML = STEPS.map((s, i) => {
		const uses = s.uses.filter((u) => can_open(u[1], u[2]));
		return `<li class="fh-step">
			<span class="fh-num">${i + 1}</span>
			<div class="fh-body">
				<h3>${esc(s.title)}</h3>
				<p>${esc(s.text)}</p>
				<div class="fh-uses" ${uses.length ? "" : "hidden"}><span>Opens:</span>
					${uses.map((u) => `<button class="fh-chip" ${target(u[1], u[2])}>${esc(u[0])}</button>`).join("")}
				</div>
			</div>
		</li>`;
	}).join("");
}

function render_records() {
	slot("records").innerHTML = RECORDS.filter((r) => can_open(r[1], r[2])).map((r) => `<button class="fh-row" ${target(r[1], r[2])}>
		<span>${esc(r[0])}</span><em>${r[1] === "Report" ? "Report" : r[1] === "Page" ? "Page" : "List"}</em>
	</button>`).join("");
}

$root.querySelectorAll(".fh-actions [data-to]").forEach((b) => {
	if (!can_open(b.dataset.type, b.dataset.to)) b.hidden = true;
});

$root.addEventListener("click", (e) => {
	const btn = e.target.closest("button");
	if (!btn) return;
	if (btn.dataset.t !== undefined) {
		const [type, to, filters] = TARGETS[+btn.dataset.t];
		go(type, to, filters);
	} else if (btn.dataset.to) {
		go(btn.dataset.type, btn.dataset.to);
	}
});

render_tiles(null, null);
render_setup(null);
render_steps();
render_records();

frappe.xcall(API + "get_home").then((h) => {
	render_tiles(h.tiles, h.academic_year);
	render_attention(h.attention);
	render_setup(h.setup);
});

style:
:host {
	--fh-brand: #920C24;
	--fh-brand-dark: #6E091B;
	--fh-brand-border: #E8B4BE;
	--fh-brand-softest: #FBEEF0;
	--fh-ok: #1F7A4D;
	--fh-font: "Merriweather", Georgia, "Times New Roman", serif;
}
.fh, .fh button { font-family: var(--fh-font); }
.fh { color: var(--text-color); font-size: 13px; line-height: 1.6; padding: 4px 0 24px; }
.fh button { cursor: pointer; }
.fh h1, .fh h2, .fh h3, .fh p { margin: 0; }
.fh [hidden] { display: none !important; }

/* header */
.fh-head { display: flex; justify-content: space-between; align-items: flex-end; gap: 16px; flex-wrap: wrap;
	padding: 4px 0 20px; border-bottom: 1px solid var(--border-color); }
.fh-head > div:first-child { flex: 1 1 360px; min-width: 0; }
.fh-head h1 { font-size: 22px; line-height: 1.35; font-weight: 700; color: var(--heading-color, var(--text-color)); }
.fh-lead { color: var(--text-muted); margin-top: 6px; max-width: 560px; }
.fh-actions { display: flex; gap: 8px; flex-wrap: wrap; }
.fh-btn { border: 1px solid var(--border-color); background: var(--card-bg); color: var(--text-color);
	border-radius: 8px; padding: 8px 14px; font-size: 12.5px; font-weight: 700; }
.fh-btn:hover { border-color: var(--fh-brand); color: var(--fh-brand); }
.fh-btn.fh-primary { background: var(--fh-brand); border-color: var(--fh-brand); color: #fff; }
.fh-btn.fh-primary:hover { background: var(--fh-brand-dark); color: #fff; }

/* sections */
.fh-sec { padding-top: 26px; }
.fh-sec-head { margin-bottom: 12px; }
.fh-tag { display: inline-block; font-size: 10.5px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--fh-brand); }
.fh-sec-head h2 { font-size: 17px; font-weight: 700; margin-top: 2px; color: var(--heading-color, var(--text-color)); }
.fh-sec-head p { color: var(--text-muted); margin-top: 2px; max-width: 640px; }

/* today tiles */
.fh-today { display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); gap: 10px; }
.fh-tile b { word-break: break-word; }
.fh-tile { display: flex; flex-direction: column; align-items: flex-start; gap: 2px; text-align: left; color: inherit;
	background: var(--card-bg); border: 1px solid var(--border-color); border-radius: 10px; padding: 12px 14px; }
.fh-tile:hover { border-color: var(--fh-brand-border); box-shadow: 0 1px 6px rgba(146, 12, 36, .08); }
.fh-tile span { font-size: 12px; color: var(--text-muted); }
.fh-tile b { font-size: 24px; line-height: 1.2; font-variant-numeric: tabular-nums; }
.fh-tile small { font-size: 11px; color: var(--text-muted); }
.fh-tile.zero b { color: var(--text-muted); }

/* attention */
.fh-attn { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; }
.fh-flag { display: flex; align-items: center; gap: 12px; text-align: left; color: inherit; width: 100%;
	background: var(--card-bg); border: 1px solid var(--border-color); border-left: 3px solid var(--fh-brand); border-radius: 10px; padding: 10px 14px; }
.fh-flag:hover { border-color: var(--fh-brand); }
.fh-flag b { font-size: 20px; min-width: 48px; font-variant-numeric: tabular-nums; color: var(--fh-brand); }
.fh-flag small { display: block; color: var(--text-muted); font-size: 11.5px; }
.fh-flag em { margin-left: auto; font-style: normal; font-weight: 700; font-size: 12px; color: var(--fh-brand); white-space: nowrap; }
.fh-calm { grid-column: 1 / -1; color: var(--text-muted); background: var(--card-bg); border: 1px dashed var(--border-color); border-radius: 10px; padding: 12px 14px; }

/* setup checklist */
.fh-setup { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 10px; }
.fh-item { display: flex; gap: 10px; align-items: flex-start; text-align: left; width: 100%;
	border: 1px solid var(--border-color); background: var(--card-bg); color: inherit; border-radius: 10px; padding: 12px; }
.fh-item:hover { border-color: var(--fh-brand-border); box-shadow: 0 1px 6px rgba(146, 12, 36, .08); }
.fh-check { flex: none; width: 20px; height: 20px; border-radius: 50%; border: 1.5px solid var(--gray-400, #c0c6cc);
	display: grid; place-items: center; font-size: 11px; color: #fff; margin-top: 1px; }
.fh-item.done .fh-check { background: var(--fh-ok); border-color: var(--fh-ok); }
.fh-item b { display: block; font-size: 13px; }
.fh-item small { display: block; color: var(--text-muted); font-size: 11.5px; line-height: 1.5; margin-top: 2px; }
.fh-state { display: inline-block; margin-top: 6px; font-size: 11px; font-weight: 700; color: var(--text-muted); }
.fh-item.done .fh-state { color: var(--fh-ok); }
.fh-item.todo .fh-state { color: var(--fh-brand); }
.fh-badge { display: inline-block; margin-left: 6px; font-size: 10px; font-weight: 700; letter-spacing: .04em; text-transform: uppercase;
	color: var(--text-muted); border: 1px solid var(--border-color); border-radius: 999px; padding: 0 7px; vertical-align: 1px; }

/* steps */
.fh-steps { list-style: none; margin: 0; padding: 0; display: grid; gap: 10px; }
.fh-step { display: flex; gap: 14px; background: var(--card-bg); border: 1px solid var(--border-color); border-radius: 10px; padding: 14px 16px; }
.fh-num { flex: none; width: 28px; height: 28px; border-radius: 50%; background: var(--fh-brand-softest); color: var(--fh-brand);
	border: 1px solid var(--fh-brand-border); display: grid; place-items: center; font-weight: 700; }
.fh-body { min-width: 0; }
.fh-body h3 { font-size: 14px; font-weight: 700; }
.fh-body p { color: var(--text-muted); margin-top: 2px; }
.fh-uses { display: flex; gap: 6px; flex-wrap: wrap; align-items: center; margin-top: 8px; }
.fh-uses > span { font-size: 11.5px; color: var(--text-muted); }
.fh-chip { border: 1px solid var(--border-color); background: var(--card-bg); color: var(--text-color); border-radius: 999px; padding: 2px 10px; font-size: 11.5px; font-weight: 700; }
.fh-chip:hover { border-color: var(--fh-brand); color: var(--fh-brand); }

/* records */
.fh-links { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 0 18px; }
.fh-row { display: flex; justify-content: space-between; align-items: center; gap: 10px; text-align: left; width: 100%;
	border: 0; border-bottom: 1px solid var(--border-color); background: none; color: inherit; padding: 9px 2px; }
.fh-row:hover span { color: var(--fh-brand); }
.fh-row em { font-style: normal; font-size: 11px; color: var(--text-muted); }

@media (max-width: 1100px) {
	.fh-today { grid-template-columns: repeat(3, minmax(0, 1fr)); }
	.fh-setup, .fh-links { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 640px) {
	.fh-today { grid-template-columns: repeat(2, minmax(0, 1fr)); }
	.fh-setup, .fh-links, .fh-attn { grid-template-columns: minmax(0, 1fr); }
}
